Algorithm Menu
  Define codigo As Integer;
  Read codigo;
  Switch codigo Do
    1:
      Write "Juice 3";
    2:
      Write "Sandwich 5";
    3:
      Write "Cookie 2";
    4:
      Write "Water 1";
    5:
      Write "Fruit 2";
    Otherwise:
      Write "Does not exist";
  EndSwitch
EndAlgorithm

Algorithm LeapYear
  Define anio As Integer;
  Read anio;
  If anio Mod 400 = 0 Then
    Write "Leap year";
  Else
    If anio Mod 100 = 0 Then
      Write "Not a leap year";
    Else
      If anio Mod 4 = 0 Then
        Write "Leap year";
      Else
        Write "Not a leap year";
      EndIf
    EndIf
  EndIf
EndAlgorithm

Algorithm LeapYear
  Define anio As Integer;
  Read anio;
  If (anio Mod 4 = 0 And anio Mod 100 <> 0) Or anio Mod 400 = 0 Then
    Write "Leap year";
  Else
    Write "Not a leap year";
  EndIf
EndAlgorithm

Algorithm Cinema
  Define dia As Integer;
  Define age As Integer;
  Read dia;
  Read age;
  If dia = 4 Then
    Write "Pays 4";
  Else
    If age < 12 Then
      Write "Pays 5";
    Else
      Write "Pays 8";
    EndIf
  EndIf
EndAlgorithm
